    EasyMock.expectLastCall().andThrow(ioex);
    EasyMock.replay(content);
    final FileHandler handler = new FileHandler(content);
    try {
        handler.save(out);
    } catch (final ConfigurationException cex) {
        assertEquals("Wrong cause", ioex, cex.getCause());
}
}

